operation.add:
$robokassa_hold_pending_status_id = (int)($this->config->get('payment_robokassa_hold_pending_status_id') ?: 1);
$robokassa_hold_confirm_status_id = (int)($this->config->get('payment_robokassa_hold_confirm_status_id') ?: 2);
$robokassa_hold_cancel_status_id = (int)($this->config->get('payment_robokassa_hold_cancel_status_id') ?: 7);
$robokassa_is_hold_cancel = $this->config->get('payment_robokassa_status_hold') && $order_info['order_status_id'] == $robokassa_hold_pending_status_id && $this->request->post['order_status_id'] == $robokassa_hold_cancel_status_id;

// Added condition for robokassa_hold_confirm
if ($this->config->get('payment_robokassa_status_hold') && $order_info['order_status_id'] == $robokassa_hold_pending_status_id && $this->request->post['order_status_id'] == $robokassa_hold_confirm_status_id) {
  $this->load->model('extension/payment/robokassa');
  if (!$this->model_extension_payment_robokassa->robokassa_hold_confirm($order_id)) {
    $json['error'] = 'Robokassa не подтвердила списание захолдированного платежа. Статус заказа не изменен.';
    $this->response->addHeader('Content-Type: application/json');
    $this->response->setOutput(json_encode($json));
    return;
  }
}
// Added condition for robokassa_hold_confirm

// Added condition for robokassa_hold_cancel
if ($robokassa_is_hold_cancel) {
  $this->load->model('extension/payment/robokassa');
  if (!$this->model_extension_payment_robokassa->robokassa_hold_cancel($order_id)) {
    $json['error'] = 'Robokassa не отменила захолдированный платеж. Статус заказа не изменен.';
    $this->response->addHeader('Content-Type: application/json');
    $this->response->setOutput(json_encode($json));
    return;
  }
}
// Added condition for robokassa_hold_cancel

// Final check
if (!$robokassa_is_hold_cancel && $order_info['order_status_id'] != $this->request->post['order_status_id'] && strpos((string)$order_info['payment_code'], 'robokassa') === 0 && $this->request->post['order_status_id'] == $this->config->get('payment_robokassa_order_status_id_2check') && $this->config->get('payment_robokassa_fiscal') == 1){
  $this->load->model('extension/payment/robokassa');

  try {
    $this->model_extension_payment_robokassa->sendSecondCheck($order_id);
  } catch (Exception $e) {
    $json['error'] = $e->getMessage();
    $this->response->addHeader('Content-Type: application/json');
    $this->response->setOutput(json_encode($json));
    return;
  }
}
// Final check

if ($this->config->get('payment_robokassa_country') == 'RUB') {
  if ($this->customer->isLogged() || !$this->config->get('config_customer_price')) {
    if ((float)$product_info['special']) {
      $robokassa_widget_amount = $this->tax->calculate($product_info['special'], $product_info['tax_class_id'], $this->config->get('config_tax'));
    } else {
      $robokassa_widget_amount = $this->tax->calculate($product_info['price'], $product_info['tax_class_id'], $this->config->get('config_tax'));
    }

    if ($robokassa_widget_amount > 0) {
      $robokassa_widget_preview = $this->load->controller('extension/payment/robokassa_widget', array(
        'product_id' => $product_id,
        'quantity' => isset($this->request->get['quantity']) ? (int)$this->request->get['quantity'] : $data['minimum']
      ));

      if ($robokassa_widget_preview !== '') {
        $this->document->addScript('catalog/view/javascript/robokassa_product_widget_mount.js', 'footer');
      }
    }
  }
}

$robokassa_graph_methods = array(
  'robokassa_mokka' => 'Mokka',
  'robokassa_podeli' => 'Podeli',
  'robokassa_yandex_split' => 'YandexPaySplit'
);
$robokassa_graph_login = trim((string)$this->config->get('payment_robokassa_login'));
$robokassa_graph_enabled = $this->config->get('payment_robokassa_status')
  && $this->config->get('payment_robokassa_country') == 'RUB'
  && $robokassa_graph_login !== ''
  && (float)$total > 0;

if ($robokassa_graph_enabled) {
  $robokassa_graph_out_sum = number_format((float)$total, 2, '.', '');

  foreach ($method_data as $robokassa_graph_code => &$robokassa_graph_method) {
    if (!isset($robokassa_graph_methods[$robokassa_graph_code])) {
      continue;
    }

    $robokassa_graph_method['robokassa_graph_payment_method'] = $robokassa_graph_methods[$robokassa_graph_code];
    $robokassa_graph_method['robokassa_graph_merchant_login'] = $robokassa_graph_login;
    $robokassa_graph_method['robokassa_graph_out_sum'] = $robokassa_graph_out_sum;
  }
  unset($robokassa_graph_method);
}

$data['robokassa_graph_enabled'] = $robokassa_graph_enabled;
$data['robokassa_graph_script'] = 'https://auth.robokassa.ru/merchant/bundle/robokassa-iframe-badge.js';

$this->session->data['payment_methods'] = $method_data;

if (isset($this->session->data['robokassa_widget_payment_code'])) {
  $robokassa_widget_payment_code = (string)$this->session->data['robokassa_widget_payment_code'];

  if ($robokassa_widget_payment_code !== '' && isset($method_data[$robokassa_widget_payment_code])) {
    $this->session->data['payment_method'] = $method_data[$robokassa_widget_payment_code];
  }

  unset($this->session->data['robokassa_widget_payment_code']);
}

{% if robokassa_graph_enabled %}
<script type="text/javascript">
(function() {
  function syncRobokassaCheckoutGraphs() {
    var graphContainers = document.querySelectorAll('.robokassa-checkout-graph');
    var activeMethods = [];

    for (var i = 0; i < graphContainers.length; i++) {
      var graphContainer = graphContainers[i];
      var radioWrapper = graphContainer.closest('.radio');
      var radioInput = radioWrapper ? radioWrapper.querySelector('input[name="payment_method"]') : null;
      var isActive = !!(radioInput && radioInput.checked);

      if (radioWrapper && radioWrapper.parentNode) {
        radioWrapper.parentNode.classList.add('robokassa-checkout-payment-list');
      }

      if (isActive) {
        graphContainer.classList.add('is-active');

        if (graphContainer.getAttribute('data-payment-method')) {
          activeMethods.push(graphContainer.getAttribute('data-payment-method'));
        }
      } else {
        graphContainer.classList.remove('is-active');
      }
    }

    if (typeof window.initRobokassaGraphs === 'function' && activeMethods.length) {
      window.initRobokassaGraphs(activeMethods.length === 1 ? activeMethods[0] : activeMethods);
    }
  }

  function bindRobokassaCheckoutGraphs() {
    var radios = document.querySelectorAll('input[name="payment_method"]');

    for (var i = 0; i < radios.length; i++) {
      if (radios[i].getAttribute('data-robokassa-graph-bound') === '1') {
        continue;
      }

      radios[i].setAttribute('data-robokassa-graph-bound', '1');
      radios[i].addEventListener('change', syncRobokassaCheckoutGraphs);
    }
  }

  function normalizeRobokassaCheckoutAgree() {
    var agrees = document.querySelectorAll('input[name="agree"]');

    for (var i = 0; i < agrees.length; i++) {
      var agree = agrees[i];
      var label = agree.closest ? agree.closest('label') : null;
      var holder = agree.closest ? agree.closest('.checkbox, .form-check') : null;
      var buttons = agree.closest ? agree.closest('.buttons') : null;
      var row = agree.closest ? agree.closest('.pull-right') : null;
      var scope = row || holder || agree.parentNode;

      if (label) {
        label.classList.add('robokassa-checkout-agree');
      }

      if (holder) {
        holder.classList.add('robokassa-checkout-agree-holder');
      }

      if (buttons) {
        buttons.classList.add('robokassa-checkout-buttons');
      }

      if (row) {
        row.classList.add('robokassa-checkout-buttons-row');
      }

      if (!label && scope && scope.getAttribute('data-robokassa-agree-normalized') !== '1') {
        scope.setAttribute('data-robokassa-agree-normalized', '1');

        var line = document.createElement('label');
        var text = document.createElement('span');
        var button = scope.querySelector('#button-payment-method, input[type="button"], button, input[type="submit"]');
        var nodes = Array.prototype.slice.call(scope.childNodes);

        line.className = 'robokassa-checkout-agree';
        text.className = 'robokassa-checkout-agree-text';

        scope.insertBefore(line, button && button.parentNode === scope ? button : scope.firstChild);
        line.appendChild(agree);
        line.appendChild(text);

        for (var j = 0; j < nodes.length; j++) {
          var node = nodes[j];

          if (node === line || node === agree || node === button) {
            continue;
          }

          if (node.nodeType === 1) {
            var tagName = node.tagName ? node.tagName.toLowerCase() : '';

            if (tagName === 'script' || tagName === 'style') {
              continue;
            }

            if (button && node.contains && node.contains(button)) {
              continue;
            }
          }

          text.appendChild(node);
        }
      }
    }
  }

  normalizeRobokassaCheckoutAgree();

  function initRobokassaCheckoutGraphs() {
    bindRobokassaCheckoutGraphs();
    normalizeRobokassaCheckoutAgree();
    syncRobokassaCheckoutGraphs();
  }

  if (window.__robokassaCheckoutGraphsLoading) {
    var waitInterval = window.setInterval(function() {
      if (typeof window.initRobokassaGraphs === 'function') {
        window.clearInterval(waitInterval);
        initRobokassaCheckoutGraphs();
      }
    }, 100);

    window.setTimeout(function() {
      window.clearInterval(waitInterval);
    }, 5000);

    return;
  }

  if (typeof window.initRobokassaGraphs === 'function') {
    initRobokassaCheckoutGraphs();
    return;
  }

  window.__robokassaCheckoutGraphsLoading = true;

  var script = document.createElement('script');
  script.src = '{{ robokassa_graph_script }}';
  script.onload = function() {
    window.__robokassaCheckoutGraphsLoading = false;
    initRobokassaCheckoutGraphs();
  };
  script.onerror = function() {
    window.__robokassaCheckoutGraphsLoading = false;
  };

  document.head.appendChild(script);
})();
</script>
<style>
 .robokassa-checkout-payment-list {
   display: block !important;
   width: 100%;
   max-width: 100%;
 }

 .robokassa-checkout-payment-list > .radio,
 .robokassa-checkout-payment-list > label,
 .robokassa-checkout-payment-list > .payment-method,
 .robokassa-checkout-payment-list > .payment-method-item,
 .robokassa-checkout-payment-list > .checkout-payment-method,
 .robokassa-checkout-payment-list > .payment-option {
   display: block !important;
   float: none !important;
   width: 100% !important;
   max-width: 100% !important;
   margin: 0 0 8px !important;
   clear: both;
   box-sizing: border-box;
 }

 .robokassa-checkout-payment-list input[name="payment_method"] {
   margin-right: 6px;
 }

 .robokassa-checkout-buttons {
   width: 100%;
   max-width: 100%;
   text-align: left;
 }

 .robokassa-checkout-buttons .pull-right {
   float: none !important;
   width: 100%;
   max-width: 100%;
   text-align: left !important;
 }

 .robokassa-checkout-buttons-row {
   float: none !important;
   width: 100%;
   max-width: 100%;
   text-align: left !important;
 }

 .robokassa-checkout-agree-holder {
   width: 100%;
   max-width: 100%;
   text-align: left !important;
 }

 .robokassa-checkout-agree {
   display: flex !important;
   align-items: flex-start !important;
   gap: 6px;
   width: 100% !important;
   max-width: 100% !important;
   margin: 0 0 14px !important;
   text-align: left !important;
   line-height: 1.4 !important;
   white-space: normal !important;
 }

 .robokassa-checkout-agree input[name="agree"] {
   flex: 0 0 auto;
   margin: 2px 0 0 !important;
   position: static !important;
   vertical-align: middle !important;
 }

 .robokassa-checkout-agree-text {
   display: block !important;
   min-width: 0;
   max-width: 100%;
   line-height: 1.4 !important;
   white-space: normal !important;
 }

 .robokassa-checkout-agree a {
   display: inline !important;
 }

 .robokassa-checkout-graph {
   display: none;
   position: relative;
   width: 690px;
   max-width: 100%;
   margin: 6px 0 0 0;
   box-sizing: border-box;
   overflow: visible;
 }

 .robokassa-checkout-graph.is-active {
   display: block;
 }

 .robokassa-checkout-graph robokassa-graph {
   display: block;
   width: 690px;
   max-width: 100%;
   box-sizing: border-box;
 }
</style>
{% endif %}

if ($extension == 'payment' && $files) {
  $robokassa_hidden_extensions = array(
    'robokassa_credit',
    'robokassa_mokka',
    'robokassa_podeli',
    'robokassa_sbp',
    'robokassa_split',
    'robokassa_widget',
    'robokassa_yandex_split'
  );

  $robokassa_payment_files = array();

  foreach ($files as $robokassa_file) {
    $robokassa_code = basename($robokassa_file, '.php');

    if (in_array($robokassa_code, $robokassa_hidden_extensions, true)) {
      continue;
    }

    $robokassa_payment_files[] = $robokassa_file;
  }

  $files = $robokassa_payment_files;
}

$this->load->model('extension/payment/robokassa');
$this->load->language('extension/payment/robokassa');

if (!isset($data['_robokassa_marking_initialized'])) {
    $data['_robokassa_marking_initialized'] = true;
    $data['robokassa_marking_enabled'] = $this->config->get('payment_robokassa_marking')
        && $this->config->get('payment_robokassa_fiscal')
        && $this->config->get('payment_robokassa_country') === 'RUB'
        && isset($order_info['payment_code'])
        && strpos((string)$order_info['payment_code'], 'robokassa') === 0;
    $data['robokassa_marking_incomplete'] = false;
    $data['column_marking'] = $this->language->get('column_marking');
    $data['text_marking_empty'] = $this->language->get('text_marking_empty');
    $data['text_marking_partial'] = $this->language->get('text_marking_partial');
    $data['text_marking_filled'] = $this->language->get('text_marking_filled');
    $data['text_marking_not_required'] = $this->language->get('text_marking_not_required');
    $data['button_marking_save'] = $this->language->get('button_marking_save');
    $data['marking_unit'] = $this->language->get('marking_unit');
    $data['warning_marking_incomplete'] = $this->language->get('warning_marking_incomplete');
    $data['error_marking_load'] = $this->language->get('error_marking_load');
    $data['error_marking_save'] = $this->language->get('error_marking_save');
    $data['robokassa_marking_get_url'] = str_replace('&amp;', '&', $this->url->link('extension/payment/robokassa/getOrderProductMarking', 'user_token=' . $this->session->data['user_token'], true));
    $data['robokassa_marking_save_url'] = str_replace('&amp;', '&', $this->url->link('extension/payment/robokassa/saveOrderProductMarking', 'user_token=' . $this->session->data['user_token'], true));

    if ($data['robokassa_marking_enabled']) {
        $this->model_extension_payment_robokassa->installMarkingTables();
        $this->document->addStyle('view/stylesheet/robokassa/marking.css');
    }
}

$robokassa_marking_required = $data['robokassa_marking_enabled']
    && $this->model_extension_payment_robokassa->isProductMarkingRequired($product['product_id']);
$robokassa_marking_status = $robokassa_marking_required
    ? $this->model_extension_payment_robokassa->getMarkingStatus($product['order_product_id'], $product['quantity'])
    : 'not_required';

if ($robokassa_marking_required && $robokassa_marking_status !== 'filled') {
    $data['robokassa_marking_incomplete'] = true;
}

{% if robokassa_marking_enabled and robokassa_marking_incomplete %}
<div class="alert alert-warning"><i class="fa fa-exclamation-triangle"></i> {{ warning_marking_incomplete }}</div>
{% endif %}

{% if robokassa_marking_enabled %}
<td class="text-center">
  {% if product.robokassa_marking_required %}
    {% set marking_class = product.robokassa_marking_status == 'filled' ? 'btn-success' : (product.robokassa_marking_status == 'partial' ? 'btn-warning' : 'btn-danger') %}
    {% set marking_text = product.robokassa_marking_status == 'filled' ? text_marking_filled : (product.robokassa_marking_status == 'partial' ? text_marking_partial : text_marking_empty) %}
    <button type="button" class="btn btn-sm {{ marking_class }} robokassa-marking-button"
            data-order-product-id="{{ product.order_product_id }}"
            data-label-empty="{{ text_marking_empty }}"
            data-label-partial="{{ text_marking_partial }}"
            data-label-filled="{{ text_marking_filled }}">
      <i class="fa fa-barcode"></i> <span class="robokassa-marking-status">{{ marking_text }}</span>
    </button>
  {% else %}
    {{ text_marking_not_required }}
  {% endif %}
</td>
{% endif %}
